// SETU 3D Official Logos (Base64 Data URIs)
// Zero external asset file dependencies — guaranteed 100% reliable across Web, Vercel, and Mobile

export const SETU_LOGO_HI_URI = "data:image/png;base64,";
export const SETU_LOGO_EN_URI = "data:image/png;base64,";

export const SETU_LOGO_HI = { uri: SETU_LOGO_HI_URI };
export const SETU_LOGO_EN = { uri: SETU_LOGO_EN_URI };

export const getSetuLogo = (lang: string) => {
  return lang === 'hi' ? SETU_LOGO_HI : SETU_LOGO_EN;
};
